/**
 * Committed contract artifacts (generated by
 * tooling/export-contract-artifacts.mjs). Deployable entries carry creation
 * and runtime bytecode, the immutable ranges and the masked runtime hash;
 * the others carry the ABI only.
 */
import type { Abi, Hex } from "viem";
import exported from "./kletia-contracts.json" with { type: "json" };

export interface ContractArtifact {
  readonly contractName: string;
  readonly sourceName: string;
  readonly project: "base" | "arc";
  readonly deployable: boolean;
  readonly compiler: { readonly solc: string; readonly optimizer: boolean; readonly runs: number; readonly evmVersion: string };
  readonly abi: Abi;
  readonly bytecode?: Hex;
  readonly deployedBytecode?: Hex;
  readonly immutableReferences?: readonly { readonly start: number; readonly length: number }[];
  readonly maskedRuntimeHash?: Hex;
  readonly runtimeHash?: Hex;
}

export interface DeployableArtifact extends ContractArtifact {
  readonly bytecode: Hex;
  readonly deployedBytecode: Hex;
  readonly immutableReferences: readonly { readonly start: number; readonly length: number }[];
  readonly maskedRuntimeHash: Hex;
  readonly runtimeHash: Hex;
}

const ARTIFACTS = (exported as unknown as { readonly schemaVersion: string; readonly artifacts: Readonly<Record<string, ContractArtifact>> }).artifacts;

export const ARTIFACT_SCHEMA_VERSION = (exported as { schemaVersion: string }).schemaVersion;

export function getArtifact(artifactId: string): ContractArtifact | null {
  return Object.prototype.hasOwnProperty.call(ARTIFACTS, artifactId) ? (ARTIFACTS[artifactId] ?? null) : null;
}

export function isDeployable(artifact: ContractArtifact | null): artifact is DeployableArtifact {
  return Boolean(artifact?.deployable && artifact.bytecode && artifact.deployedBytecode && artifact.maskedRuntimeHash);
}

export function artifactIds(): string[] {
  return Object.keys(ARTIFACTS);
}
